package com.subrosa.desktop

import org.junit.jupiter.api.Test
import org.junit.jupiter.api.Assertions as A
import java.io.File
import java.security.KeyFactory
import java.security.Signature
import java.security.spec.X509EncodedKeySpec
import java.util.Base64

/**
 * KL-13: shared golden invite vectors, read by BOTH clients.
 *
 * `testdata/invite-vectors.tsv` (repo root) is generated by an independent
 * Python implementation (testdata/gen_invite_vectors.py). The identical test
 * lives in app/src/test/.../InviteVectorsTest.kt and reads the same
 * file, so a divergence between the two parsers shows up as one of the two
 * suites failing on the same row.
 *
 * All vectors carry a fixed 2025 timestamp, i.e. they are expired by design:
 * we check the parse result, an independent java.security ECDSA verification
 * of the signature (so "sig_valid" does not depend on the code under test),
 * and that verifyInviteCode() refuses them (7-day TTL).
 */
class InviteVectorsTest {

    private class Row(val cols: List<String>) {
        val id get() = cols[0]
        val code get() = cols[1]
        val parseOk get() = cols[2] == "1"
        val fingerprint get() = cols[3]
        val nonce get() = cols[4]
        val tag get() = cols[5]
        val name get() = String(cols[6].chunked(2).map { it.toInt(16).toByte() }.toByteArray(), Charsets.UTF_8)
        val timestamp get() = cols[7].toLong()
        val sigValid get() = cols[8] == "1"
    }

    private fun rows(): List<Row> {
        val f = listOf("../testdata/invite-vectors.tsv", "testdata/invite-vectors.tsv")
            .map { File(it) }.first { it.isFile }
        return f.readLines(Charsets.UTF_8).filter { it.isNotBlank() && !it.startsWith("#") }
            .map { Row(it.split('\t')) }
    }

    /** Independent of InviteCodeManager: raw r||s -> DER, verify with java.security. */
    private fun independentSigValid(code: String): Boolean = try {
        val payload = Base64.getUrlDecoder().decode(code.removePrefix("bc:"))
        val pre = payload.copyOfRange(0, payload.size - 64)
        val raw = payload.copyOfRange(payload.size - 64, payload.size)
        val ecPoint = pre.copyOfRange(1 + 4 + 8 + 16 + 8, 1 + 4 + 8 + 16 + 8 + 65)
        val hdr = "3059301306072a8648ce3d020106082a8648ce3d030107034200".chunked(2).map { it.toInt(16).toByte() }.toByteArray()
        val pub = KeyFactory.getInstance("EC").generatePublic(X509EncodedKeySpec(hdr + ecPoint))
        fun der(b: ByteArray): ByteArray {
            val s = b.dropWhile { it == 0.toByte() }.toByteArray().let { if (it.isEmpty()) byteArrayOf(0) else it }
            val v = if (s[0].toInt() and 0x80 != 0) byteArrayOf(0) + s else s
            return byteArrayOf(0x02, v.size.toByte()) + v
        }
        val body = der(raw.copyOfRange(0, 32)) + der(raw.copyOfRange(32, 64))
        Signature.getInstance("SHA256withECDSA").apply { initVerify(pub); update(pre) }
            .verify(byteArrayOf(0x30, body.size.toByte()) + body)
    } catch (e: Exception) {
        false
    }

    @Test
    fun `vector file is present and non-trivial`() {
        val r = rows()
        assertTrue("expected >= 10 vectors, got ${r.size}", r.size >= 10)
        assertTrue(r.any { it.parseOk } && r.any { !it.parseOk })
    }

    @Test
    fun `every vector parses exactly as the shared file says`() {
        for (row in rows()) {
            val d = InviteCodeManager.parseInviteCode(row.code)
            if (!row.parseOk) {
                assertNull("[${row.id}] must be rejected at parse", d)
                continue
            }
            assertNotNull("[${row.id}] must parse", d)
            assertEquals("[${row.id}] fingerprint", row.fingerprint, d!!.fingerprint)
            assertEquals("[${row.id}] nonce", row.nonce, d.nonce)
            assertEquals("[${row.id}] mailbox tag", row.tag, d.mailboxTag)
            assertEquals("[${row.id}] name", row.name, d.displayName)
            assertEquals("[${row.id}] timestamp", row.timestamp, d.timestamp)
        }
    }

    @Test
    fun `signatures in the file are what the file claims, by independent verification`() {
        for (row in rows().filter { it.parseOk }) {
            assertEquals("[${row.id}] sig_valid", row.sigValid, independentSigValid(row.code))
        }
    }

    @Test
    fun `expired vectors are refused by verifyInviteCode`() {
        for (row in rows().filter { it.parseOk }) {
            val d = InviteCodeManager.parseInviteCode(row.code)!!
            assertFalse("[${row.id}] is years old and must fail the 7-day TTL", InviteCodeManager.verifyInviteCode(d))
        }
    }
}

// JUnit-4-style argument order (message first) so the body matches the Android twin line for line.
private fun assertEquals(msg: String, expected: Any?, actual: Any?) = A.assertEquals(expected, actual, msg)
private fun assertTrue(msg: String, c: Boolean) = A.assertTrue(c, msg)
private fun assertTrue(c: Boolean) = A.assertTrue(c)
private fun assertFalse(msg: String, c: Boolean) = A.assertFalse(c, msg)
private fun assertNull(msg: String, v: Any?) = A.assertNull(v, msg)
private fun assertNotNull(msg: String, v: Any?) = A.assertNotNull(v, msg)
